  emission_alpha?: Maybe<Scalars['Float']['output']>;
  hotkey?: Maybe<Scalars['String']['output']>;
  incentive?: Maybe<Scalars['Float']['output']>;
  is_immunity_period?: Maybe<Scalars['Boolean']['output']>;
